    /* Failure handling: Null pointers check first */
    if ((minimum_margin == NULL) || (limit limiting_index == NULL) || 
        (momentum == NULL) || (reserve_vector == NULL)) {
        return ADCS_E_NULL;
    }

    /* Otherwise outputs are first set to default values */
    *minimum_margin = INFINITY;
    *limiting_index = SIZE_MAX;
    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    *reserve_vector = (adcs_vec3_t){0.0, 0.0, 0.0};

    /* Then null wheels/speed_limits check */
    if ((wheels == NULL) || (speed_limits == NULL)) {
        return ADCS_E_NULL;
    }

    /* Count outside 1..16 check */
    if ((count < 1) || (count > 16)) {
        return ADCS_E_RANGE;
    }

    /* Validate each wheel parameters */
    for (size_t i = 0; i < count; ++i) {
        double sl = speed_limits[i];
        double inertia = wheels[i].inertia_kg_m2;
        double speed = wheels[i].speed_rad_s;
        adcs_vec3_t axis = wheels[i].axis_body;

        /* Any nonfinite or nonpositive speed limit */
        if ((!isfinite(sl)) || (sl <= 0.0)) {
            return ADCS_E_RANGE;
        }

        /* Nonfinite or nonpositive inertia */
        if ((!isfinite(inertia)) || (inertia <= 0.0)) {
            return ADCS_E_RANGE;
        }

        /* Nonfinite speed */
        if (!isfinite(speed)) {
            return ADCS_E_RANGE;
        }

        /* Axis with norm <= ADCS_EPS_NORM (or nonfinite) */
        if (!adcs_is_finite_vec3(&axis)) {
            return ADCS_E_RANGE;
        }
        double axis_norm = adcs_vec3_norm(&axis);
        if (axis_norm <= ADCS_EPS_NORM) {
            return ADCS_E_RANGE;
        }
    }

    /* Find the minimum signed speed margin and its first index */
    double min_margin = INFINITY;
    size_t lim_idx = SIZE_MAX;

    for (size_t i = 0; i < count; ++i) {
        double abs_speed = fabs(wheels[i].speed_rad_s);
        double margin = speed_limits[i] - abs_speed;

        /* strict less than ensures we pick the first index for ties */
        if (margin < min_margin) {
            min_margin = margin;
            lim_idx = i;
        }
    }

    *minimum_margin = min_margin;
    *limiting_index = lim_idx;

    /* Accumulate the corresponding directional momentum reserve */
    adcs_vec3_t res_vec = {0.0, 0.0, 0.0};
    for (size_t i = 0; i < count; ++i) {
        adcs_vec3_t unit_axis;
        /* Normalize axis. Since we validated norm > EPS, this returns ADCS_OK */
        adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &unit_axis);

        double abs_speed = fabs(wheels[i].speed_rad_s);
        double margin = speed_limits[i] - abs_speed;
        double scalar = wheels[i].inertia_kg_m2 * margin;

        adcs_vec3_t term = adcs_vec3_scale(&unit_axis, scalar);
        res_vec = adcs_vec3_add(&res_vec, &term);
    }
    *reserve_vector = res_vec;

    /* Return current linked-library cluster momentum */
    adcs_wheel_momentum(wheels, count, momentum);

    return ADCS_OK;
}

